import { Activity, BookOpen, CalendarDays, Flame, Target } from "lucide-react";
import { useMemo } from "react";
import type { DrawerNote } from "@leafia/shared";
import type { ReaderBook } from "../../lib/readerLibrary";
import { CardDeck } from "../deck/CardDeck";
import { LeafFlip } from "../paper/LeafFlip";
import { buildRecentLearning, buildStudyCharts } from "./recentLearning";
import type { StudyEvent } from "./studyLog";
import "./recent-learning.css";

export function RecentLearningHub({
  events,
  notes,
  books,
  model: suppliedModel,
}: {
  events: StudyEvent[];
  notes: DrawerNote[];
  books: ReaderBook[];
  model?: ReturnType<typeof buildRecentLearning>;
}) {
  const model = useMemo(
    () => suppliedModel ?? buildRecentLearning(events, notes, books),
    [books, events, notes, suppliedModel],
  );
  const charts = useMemo(() => buildStudyCharts(events), [events]);
  // 条形图的高度按这几周里最忙的那天定标尺，矮的那几天才看得出差别。
  const peak = Math.max(1, ...charts.days.map((day) => day.total));

  return (
    <section className="recent-learning" aria-label="最近学习">
      <header className="recent-learning__head">
        <span>
          <small>Recent learning</small>
          <strong>最近学习</strong>
        </span>
        <em>
          {events.length} 条记录 · {model.books.length} 本可浏览
        </em>
      </header>

      {/* 数据图：近两周每天的三条线，加上几项成色指标。 */}
      <div className="recent-learning__charts">
        <article className="recent-learning__chart">
          <h4>
            <Activity size={14} />
            近两周的节奏
          </h4>
          <div className="recent-chart__bars" role="img" aria-label="近两周每天的学习次数">
            {charts.days.map((day) => (
              <span
                key={day.id}
                className="recent-chart__bar"
                title={`${day.label} · 读 ${day.reading} · 练 ${day.practice} · 复习 ${day.review}`}
              >
                <i
                  className="is-review"
                  style={{ height: `${(day.review / peak) * 100}%` }}
                />
                <i
                  className="is-practice"
                  style={{ height: `${(day.practice / peak) * 100}%` }}
                />
                <i
                  className="is-reading"
                  style={{ height: `${(day.reading / peak) * 100}%` }}
                />
              </span>
            ))}
          </div>
          <div className="recent-chart__axis">
            <span>{charts.days[0]?.label}</span>
            <span>{charts.days[Math.floor(charts.days.length / 2)]?.label}</span>
            <span>{charts.days[charts.days.length - 1]?.label}</span>
          </div>
          <ul className="recent-chart__legend">
            <li className="is-reading">阅读</li>
            <li className="is-practice">练习</li>
            <li className="is-review">复习</li>
          </ul>
        </article>

        <article className="recent-learning__chart is-stats">
          <h4>
            <Target size={14} />
            成色
          </h4>
          <dl className="recent-chart__stats">
            <div>
              <dt>
                <Flame size={13} />
                连续
              </dt>
              <dd>
                <strong>{charts.streak}</strong>
                <small>天</small>
              </dd>
            </div>
            <div>
              <dt>打卡</dt>
              <dd>
                <strong>{charts.activeDays}</strong>
                <small>/ 14 天</small>
              </dd>
            </div>
            <div>
              <dt>动作</dt>
              <dd>
                <strong>{charts.total}</strong>
                <small>次</small>
              </dd>
            </div>
          </dl>
          {(
            [
              ["练习正确率", charts.accuracy],
              ["复习通过率", charts.reviewPass],
            ] as Array<[string, number | null]>
          ).map(([label, value]) => (
            <div className="recent-chart__meter" key={label}>
              <span>
                {label}
                <em>{value === null ? "—" : `${value}%`}</em>
              </span>
              <i>
                <span style={{ width: `${value ?? 0}%` }} />
              </i>
            </div>
          ))}
        </article>
      </div>

      {model.cards.length || model.leaves.length ? (
        <div className="recent-learning__grid">
          <article className="recent-learning__panel">
            <h4>
              <BookOpen size={14} />
              最近读到的
            </h4>
            {model.cards.length ? (
              <CardDeck
                items={model.cards.map((card) => ({
                  id: card.id,
                  word: card.title,
                  meaning: card.subtitle,
                  image: card.src,
                }))}
                className="recent-learning__bend"
                emptyLabel="还没有打开过书本。"
              />
            ) : (
              <p>还没有打开过书本。</p>
            )}
          </article>
          <article className="recent-learning__panel">
            <h4>
              <CalendarDays size={14} />
              学习记录
            </h4>
            {model.leaves.length ? (
              <LeafFlip leaves={model.leaves} className="recent-learning__flip" />
            ) : (
              <p>开始阅读或练习后，这里会出现可翻阅的记录。</p>
            )}
          </article>
        </div>
      ) : (
        <p className="recent-learning__empty">
          还没有最近学习记录。打开一本书、点开章节或弹一段琴键后，这里会自己长出来。
        </p>
      )}
    </section>
  );
}

export default RecentLearningHub;
