import { useEffect, useRef, useState } from "react";
import { isPortraitPhone, watchPortraitPhone } from "./portraitMode";
import "./rotate-gate.css";

/**
 * 「请旋转手机」引导遮罩：只在手机竖屏出现。
 *
 * 书房是按横屏布置的（整面书架 + 琴键横着铺开），竖屏进来先请用户把手机
 * 横过来；横不了的用户（系统锁了旋转方向）点底部的「仍然竖屏浏览」即可
 * 撤掉遮罩，页面切进竖屏降级布局（见 portrait-room.css）。
 *
 * 「仍然竖屏浏览」的选择记在 sessionStorage：同一个会话里不再拦第二次，
 * 换个会话会重新问一遍 —— 引导的目的就是把横屏说一次，而不是每次都堵门。
 */
const OPT_IN_KEY = "leafia:portrait-opt-in:v1";

function readOptIn(): boolean {
  try {
    return window.sessionStorage.getItem(OPT_IN_KEY) === "1";
  } catch {
    // 隐私模式里 sessionStorage 会抛错：当作没同意过。
    return false;
  }
}

export function RotateGate() {
  const [portrait, setPortrait] = useState(isPortraitPhone);
  const [optedIn, setOptedIn] = useState(readOptIn);
  const skipRef = useRef<HTMLButtonElement | null>(null);

  useEffect(() => watchPortraitPhone(setPortrait), []);

  useEffect(() => {
    if (!portrait || optedIn) return undefined;
    // 遮罩出现时把焦点交给唯一的按钮：键盘与读屏进来都只看见这一件事。
    const timer = window.setTimeout(() => skipRef.current?.focus(), 0);
    return () => window.clearTimeout(timer);
  }, [portrait, optedIn]);

  if (!portrait || optedIn) return null;

  const handleOptIn = () => {
    setOptedIn(true);
    try {
      window.sessionStorage.setItem(OPT_IN_KEY, "1");
    } catch {
      // 存不下就只在这次停留里生效，刷新后重新问一遍。
    }
  };

  return (
    <div
      className="portrait-gate"
      role="dialog"
      aria-modal="true"
      aria-labelledby="portrait-gate-title"
      aria-describedby="portrait-gate-copy"
    >
      <div className="portrait-gate__card">
        <span className="portrait-gate__phone" aria-hidden="true">
          <i />
        </span>
        <small className="portrait-gate__kicker">Rotate your phone</small>
        <h2 id="portrait-gate-title">请把手机横过来</h2>
        <p id="portrait-gate-copy">
          书房和琴键是按横屏布置的，横过来能一次看到整面书架。
        </p>
        <button
          ref={skipRef}
          type="button"
          className="portrait-gate__skip"
          onClick={handleOptIn}
        >
          仍然竖屏浏览
        </button>
      </div>
    </div>
  );
}
