import {
  Bookmark,
  Files,
  GraduationCap,
  LibraryBig,
  NotebookPen,
  Search,
} from "lucide-react";

/**
 * 竖屏书房下半段的学习面板（长相在 portrait-room.css，只在手机竖屏展开）。
 *
 * 竖屏降级布局把书房钉在上半屏，这块可上下滑的区域就是「下半部分」的
 * 全部内容：查词、语料库、学习记录这些入口收在这里，条目走的仍是书房
 * 自己的通道 —— 抽屉类开的是房间里的浮层（和点柜子上的抽屉同一条路），
 * 页面类交给 goToSpacePath。
 */
interface PortraitStudyPanelProps {
  onOpenSpace: (path: string) => void;
  onOpenDrawer: (drawerId: "notes" | "materials" | "collection") => void;
  onFocusShelf: () => void;
}

const ENTRIES: Array<{
  key: string;
  icon: typeof Search;
  zh: string;
  detail: string;
  space?: string;
  drawer?: "notes" | "materials" | "collection";
}> = [
  {
    key: "lookup",
    icon: Search,
    zh: "查词",
    detail: "单词本 · 收词与释义",
    space: "/vocabulary",
  },
  {
    key: "corpus",
    icon: Files,
    zh: "语料库",
    detail: "例句 · 搭配 · 检索",
    space: "/corpus",
  },
  {
    key: "recent",
    icon: NotebookPen,
    zh: "学习记录",
    detail: "最近的书本与复习",
    drawer: "notes",
  },
  {
    key: "knowledge",
    icon: LibraryBig,
    zh: "知识库",
    detail: "语言学 · 文学 · 翻译",
    space: "/library",
  },
  {
    key: "practice",
    icon: GraduationCap,
    zh: "练习册",
    detail: "语音 · 词汇 · 结构",
    space: "/practice",
  },
  {
    key: "collection",
    icon: Bookmark,
    zh: "词汇积累",
    detail: "选词 · 翻卡 · 拼写",
    drawer: "collection",
  },
];

export function PortraitStudyPanel({
  onOpenSpace,
  onOpenDrawer,
  onFocusShelf,
}: PortraitStudyPanelProps) {
  return (
    <section className="portrait-study-panel" aria-label="竖屏学习面板">
      <header className="portrait-study-panel__ledge">
        <span aria-hidden="true" />
        <small>竖屏模式 · portrait</small>
      </header>

      <p className="portrait-study-panel__lede">
        书房固定在上半屏。查词、语料库和学习记录都在这块面板里，往下滑还有。
      </p>

      <div className="portrait-study-panel__grid">
        {ENTRIES.map((entry) => {
          const Icon = entry.icon;
          return (
            <button
              type="button"
              key={entry.key}
              className="portrait-study-panel__entry"
              onClick={() =>
                entry.drawer
                  ? onOpenDrawer(entry.drawer)
                  : onOpenSpace(entry.space ?? "/shelf")
              }
            >
              <span className="portrait-study-panel__icon" aria-hidden="true">
                <Icon size={17} />
              </span>
              <span className="portrait-study-panel__copy">
                <strong>{entry.zh}</strong>
                <small>{entry.detail}</small>
              </span>
            </button>
          );
        })}
      </div>

      <footer className="portrait-study-panel__footer">
        <p>
          书架上的书和琴键照旧可以直接点；想看清楚，双指在书架上捏开就进近景。
        </p>
        <button type="button" onClick={onFocusShelf}>
          进入书架近景
        </button>
      </footer>
    </section>
  );
}
