import {
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
  type UIEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./card-rail.css";

export interface RailCard {
  id: string;
  title: string;
  /** 卡面上的小标（分类、编号之类）。 */
  kicker?: string;
  /** 标题下面那行说明。 */
  meta?: string;
  /** 主题色相 0..360；不传按 id 推一个稳定的。 */
  hue?: number;
  /** 有图就铺满整张卡当底。 */
  image?: string;
}

export interface CardRailProps {
  items: RailCard[];
  onSelect?: (item: RailCard) => void;
  className?: string;
  emptyLabel?: string;
  hint?: string;
}

/** 拖多远才算真拖起来了（再小就是点一下）。 */
const DRAG_AFTER = 6;

/** 由 id 推一个稳定的 0..1，让同一张卡每次都是同一个色相。 */
function stableRatio(id: string) {
  let hash = 2166136261;
  for (let i = 0; i < id.length; i += 1) {
    hash = Math.imul(hash ^ id.charCodeAt(i), 16777619);
  }
  hash ^= hash >>> 15;
  return ((hash >>> 0) % 100000) / 100000;
}

const hueOf = (card: RailCard) => card.hue ?? Math.round(stableRatio(card.id) * 360);

/**
 * 一条横着的卡片带：一排书脊似的卡，点哪张开哪张。
 *
 * 滚动交给原生的 overflow + scroll-snap —— 触摸板上就是原生的手感，窄屏上
 * 也能左右推。这里只管三件事：把滚轮的纵向分量转成横向、按住能拖、以及
 * 标出「眼下是哪张」（指着的、键盘选中的、或者滚到正中间的）。
 *
 * 宽度够的时候几张卡并排摆着，不用滚动；够不着才出现横向滚动。
 */
export function CardRail({
  items,
  onSelect,
  className,
  emptyLabel = "这里还没有卡片。",
  hint = "拖动 / 滚轮换一张 · 点一本打开",
}: CardRailProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const trackRef = useRef<HTMLDivElement | null>(null);
  const dragRef = useRef<{
    pointerId: number;
    startX: number;
    startScroll: number;
    dragged: boolean;
  } | null>(null);
  /** 松手那一下的 click 是跟着 pointerup 来的，那时 dragRef 已经清了 —— 单独记一笔。 */
  const draggedRef = useRef(false);
  const frameRef = useRef(0);
  /** 滚到正中间的那张；没滚过就是 null。 */
  const [centeredIndex, setCenteredIndex] = useState<number | null>(null);
  /** 鼠标正指着的那张。 */
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const [focusIndex, setFocusIndex] = useState<number | null>(null);

  const activeIndex = hoverIndex ?? focusIndex ?? centeredIndex;

  /** 谁离带子中心最近。 */
  const nearestIndex = useCallback(() => {
    const track = trackRef.current;
    if (!track) return 0;
    const middle = track.scrollLeft + track.clientWidth / 2;
    let nearest = 0;
    let nearestDistance = Number.POSITIVE_INFINITY;
    track.querySelectorAll<HTMLElement>("[data-rail-card]").forEach((card, index) => {
      const distance = Math.abs(card.offsetLeft + card.offsetWidth / 2 - middle);
      if (distance < nearestDistance) {
        nearestDistance = distance;
        nearest = index;
      }
    });
    return nearest;
  }, []);

  const handleScroll = useCallback(
    (_event: UIEvent<HTMLDivElement>) => {
      if (frameRef.current) return;
      frameRef.current = window.requestAnimationFrame(() => {
        frameRef.current = 0;
        const track = trackRef.current;
        // 滚过之后指针底下已经换了一张卡，先前记的悬停不作数了。
        setHoverIndex(null);
        // 没滚动的带子（几张卡并排就摆得下）不点灯，免得凭空有一张像被选中。
        setCenteredIndex(track && track.scrollLeft > 1 ? nearestIndex() : null);
      });
    },
    [nearestIndex],
  );

  useEffect(
    () => () => {
      if (frameRef.current) window.cancelAnimationFrame(frameRef.current);
    },
    [],
  );

  /** 把某张卡带到眼前（居中；首尾两张到边就贴着边）。 */
  const center = useCallback(
    (index: number) => {
      const track = trackRef.current;
      const card = track?.querySelectorAll<HTMLElement>("[data-rail-card]")[index];
      if (!track || !card) return;
      track.scrollTo({
        left: card.offsetLeft + card.offsetWidth / 2 - track.clientWidth / 2,
        behavior: prefersReducedMotion ? "auto" : "smooth",
      });
    },
    [prefersReducedMotion],
  );

  /** 纵向滚轮推到带子上时转成横向走 —— 鼠标用户不用按着 Shift。 */
  const handleWheel = useCallback((event: WheelEvent) => {
    const track = trackRef.current;
    if (!track) return;
    if (track.scrollWidth - track.clientWidth < 2) return;
    const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
    const next = track.scrollLeft + delta;
    // 到两头就交还给页面，别把整页的滚动锁死。
    if (next <= 0 || next >= track.scrollWidth - track.clientWidth) return;
    event.preventDefault();
    track.scrollLeft = next;
  }, []);

  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    track.addEventListener("wheel", handleWheel, { passive: false });
    return () => track.removeEventListener("wheel", handleWheel);
  }, [handleWheel]);

  const handlePointerDown = useCallback((event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    const track = trackRef.current;
    if (!track) return;
    draggedRef.current = false;
    dragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startScroll: track.scrollLeft,
      dragged: false,
    };
  }, []);

  const handlePointerMove = useCallback((event: PointerEvent<HTMLDivElement>) => {
    const track = trackRef.current;
    const drag = dragRef.current;
    if (!track || !drag || drag.pointerId !== event.pointerId) return;
    const dx = event.clientX - drag.startX;
    if (!drag.dragged) {
      if (Math.abs(dx) < DRAG_AFTER) return;
      drag.dragged = true;
      draggedRef.current = true;
      track.classList.add("is-dragging");
      track.setPointerCapture?.(event.pointerId);
    }
    track.scrollLeft = drag.startScroll - dx;
  }, []);

  const endDrag = useCallback((event: PointerEvent<HTMLDivElement>) => {
    const track = trackRef.current;
    const drag = dragRef.current;
    dragRef.current = null;
    if (!track || !drag || drag.pointerId !== event.pointerId) return;
    track.classList.remove("is-dragging");
    // 松手归位：把刚才拖到的那张稳稳对到中间。
    if (drag.dragged) center(nearestIndex());
  }, [center, nearestIndex]);

  /** 左右键在卡之间走，顺手把它带到中间。Enter 交给按钮自己的 click。 */
  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>, index: number) => {
      const step =
        event.key === "ArrowRight" || event.key === "ArrowDown"
          ? 1
          : event.key === "ArrowLeft" || event.key === "ArrowUp"
            ? -1
            : 0;
      if (step === 0) return;
      event.preventDefault();
      const next = Math.min(Math.max(index + step, 0), items.length - 1);
      if (next === index) return;
      // 用键盘走的这一下，鼠标要是碰巧还停在哪张卡上，别让那点悬停盖过键盘选的这张。
      setHoverIndex(null);
      setFocusIndex(next);
      // preventScroll：不然浏览器把新焦点滚进可视区的那一下是「瞬时滚」，
      // 会把 center() 正在走的平滑滚动直接掐掉，卡就停在原地不动。
      trackRef.current
        ?.querySelectorAll<HTMLElement>("[data-rail-card]")
        [next]?.focus({ preventScroll: true });
      center(next);
    },
    [center, items.length],
  );

  if (items.length === 0) {
    return (
      <div className={["card-rail", "card-rail--empty", className].filter(Boolean).join(" ")}>
        <p className="card-rail__empty">{emptyLabel}</p>
      </div>
    );
  }

  return (
    <div className={["card-rail", className].filter(Boolean).join(" ")}>
      <div
        ref={trackRef}
        className={["card-rail__track", prefersReducedMotion && "is-static"]
          .filter(Boolean)
          .join(" ")}
        role="group"
        aria-label="卡片带"
        onScroll={handleScroll}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onPointerLeave={() => {
          setHoverIndex(null);
          setFocusIndex(null);
        }}
      >
        {items.map((card, index) => {
          const hue = hueOf(card);
          return (
            <button
              type="button"
              key={card.id}
              data-rail-card=""
              aria-current={index === activeIndex ? "true" : undefined}
              className={["card-rail__card", index === activeIndex && "is-focus"]
                .filter(Boolean)
                .join(" ")}
              style={
                {
                  "--rail-tint": `hsl(${hue} 42% 94%)`,
                  "--rail-deep": `hsl(${hue} 38% 58%)`,
                } as CSSProperties
              }
              onPointerMove={() => setHoverIndex(index)}
              onFocus={() => setFocusIndex(index)}
              onBlur={() => setFocusIndex(null)}
              onClick={() => {
                if (draggedRef.current) {
                  draggedRef.current = false;
                  return;
                }
                onSelect?.(card);
              }}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {card.image ? (
                <img className="card-rail__image" src={card.image} alt="" />
              ) : (
                <span className="card-rail__face">
                  {card.kicker ? (
                    <span className="card-rail__kicker">{card.kicker}</span>
                  ) : null}
                  <span className="card-rail__title">{card.title}</span>
                  {card.meta ? <span className="card-rail__meta">{card.meta}</span> : null}
                </span>
              )}
              <span className="card-rail__edge" aria-hidden="true" />
            </button>
          );
        })}
      </div>
      {hint ? <p className="card-rail__hint">{hint}</p> : null}
    </div>
  );
}

export default CardRail;
