import {
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
  type WheelEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./card-deck.css";

export interface DeckCard {
  id: string;
  /** 卡面主词。有图时只留给读屏。 */
  word: string;
  /** 一两个字的标记，比如词性或来源。 */
  tag?: string;
  /** 释义或用例，一到两行。 */
  meaning?: string;
  /** 已复习轮次，卡脚小字。 */
  rounds?: number;
  /** 有图就铺满卡面，文字不再叠加。 */
  image?: string;
  /** 主题色相 0..360；不传按 id 推一个稳定的。 */
  hue?: number;
  /** 卡面底色；不传按色相算。 */
  tint?: string;
  /** 卡脚色带颜色。 */
  deep?: string;
  /** 卡脚的三格小样。 */
  swatch?: string[];
}

export interface CardDeckProps {
  items: DeckCard[];
  onSelect?: (item: DeckCard) => void;
  className?: string;
  emptyLabel?: string;
  /** 盘子下方那行操作提示。 */
  hint?: string;
  initialIndex?: number;
  cardWidth?: number;
  cardHeight?: number;
}

const DEFAULT_WIDTH = 208;
const DEFAULT_HEIGHT = 264;
/** 同时可见的卡数，再往后直接不渲染。 */
const VISIBLE = 4;
/** 每退一层：往上抬、往右挪、转多少、缩多少。 */
const STEP_LIFT = 26;
const STEP_SHIFT = 16;
const STEP_TILT = 5;
const STEP_SCALE = 0.92;
/** 每退一层减多少不透明度、加多少模糊。 */
const STEP_FADE = 0.22;
const STEP_BLUR = 4;
/** 拖动多远算翻一页。 */
const DRAG_THRESHOLD = 56;
/** 手指/指针挪过这么多才算「拖起来了」，这时候才把指针收过来。 */
const CAPTURE_AFTER = 6;
/** 滚轮两次翻页之间的静默期（毫秒）。 */
const WHEEL_COOLDOWN = 260;

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

/** 由 id 推一个稳定的 0..1 数，让同一张卡每次都是同一个色相。 */
function stableRatio(id: string, salt: number) {
  let hash = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i += 1) {
    hash = Math.imul(hash ^ id.charCodeAt(i), 16777619);
  }
  hash ^= hash >>> 15;
  return ((hash >>> 0) % 100000) / 100000;
}

/** 没显式给颜色时，按色相算一套纸色 / 色带色。 */
function paletteFor(card: DeckCard) {
  const hue = card.hue ?? Math.round(stableRatio(card.id, 7) * 360);
  return {
    tint: card.tint ?? `hsl(${hue} 42% 94%)`,
    deep: card.deep ?? `hsl(${hue} 38% 62%)`,
  };
}

/**
 * 卡盘：中间一张正面朝前，后面的卡逐层后退、缩小、变暗，形成纵深。
 * 拖动或滚轮翻页，点中间那张选中。
 *
 * 位移全交给 CSS transform + transition，翻页只改 active 索引；
 * 拖动过程只记位移量，松手才决定翻不翻，免得和过渡打架。
 */
export function CardDeck({
  items,
  onSelect,
  className,
  emptyLabel = "这里还没有卡片。",
  hint = "拖动 / 滚轮翻页 · 点中间那张打开",
  initialIndex = 0,
  cardWidth = DEFAULT_WIDTH,
  cardHeight = DEFAULT_HEIGHT,
}: CardDeckProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const dragRef = useRef<{
    pointerId: number;
    startX: number;
    captured: boolean;
  } | null>(null);
  // 拖完那一下松手时也会落在某张卡上，别让 click 再翻一次。
  const draggedRef = useRef(false);
  const wheelAtRef = useRef(0);
  const last = Math.max(items.length - 1, 0);
  const [active, setActive] = useState(() => clamp(initialIndex, 0, last));

  // 卡片换了一组（换皮肤、换一批词）就回到合法范围。
  useEffect(() => {
    setActive((current) => clamp(current, 0, last));
  }, [last]);

  const step = useCallback(
    (delta: number) => setActive((current) => clamp(current + delta, 0, last)),
    [last],
  );

  const handlePointerDown = useCallback((event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    draggedRef.current = false;
    dragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      captured: false,
    };
  }, []);

  /** 真挪起来了才收指针：一按下就收，松手那下 click 会被投给盘子，卡自己收不到。 */
  const handlePointerMove = useCallback((event: PointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId || drag.captured) return;
    if (Math.abs(event.clientX - drag.startX) < CAPTURE_AFTER) return;
    drag.captured = true;
    event.currentTarget.setPointerCapture?.(event.pointerId);
  }, []);

  const handlePointerUp = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      dragRef.current = null;
      if (!drag || drag.pointerId !== event.pointerId) return;
      const dx = event.clientX - drag.startX;
      if (Math.abs(dx) < DRAG_THRESHOLD) return;
      draggedRef.current = true;
      // 往左拖 = 看下一张。
      step(dx < 0 ? 1 : -1);
    },
    [step],
  );

  const handleWheel = useCallback(
    (event: WheelEvent<HTMLDivElement>) => {
      if (items.length < 2) return;
      const now = event.timeStamp;
      if (now - wheelAtRef.current < WHEEL_COOLDOWN) return;
      const delta =
        Math.abs(event.deltaY) >= Math.abs(event.deltaX)
          ? event.deltaY
          : event.deltaX;
      if (Math.abs(delta) < 4) return;
      wheelAtRef.current = now;
      step(delta > 0 ? 1 : -1);
    },
    [items.length, step],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowRight" || event.key === "ArrowDown") {
        event.preventDefault();
        step(1);
        return;
      }
      if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
        event.preventDefault();
        step(-1);
        return;
      }
      if (event.key === "Enter" || event.key === " ") {
        const current = items[active];
        if (!current) return;
        event.preventDefault();
        onSelect?.(current);
      }
    },
    [active, items, onSelect, step],
  );

  if (items.length === 0) {
    return (
      <div
        className={["card-deck", "card-deck--empty", className]
          .filter(Boolean)
          .join(" ")}
      >
        <p className="card-deck__empty">{emptyLabel}</p>
      </div>
    );
  }

  // 卡的尺寸在盘子上定，卡片、卡脚、底下那行提示都从这儿取。
  const deckStyle = {
    "--deck-card-w": `${cardWidth}px`,
    "--deck-card-h": `${cardHeight}px`,
  } as CSSProperties;

  return (
    <div
      className={["card-deck", className].filter(Boolean).join(" ")}
      style={deckStyle}
    >
      <div
        className={[
          "card-deck__stage",
          prefersReducedMotion && "is-static",
        ]
          .filter(Boolean)
          .join(" ")}
        role="listbox"
        tabIndex={0}
        aria-label="卡片盘"
        aria-activedescendant={`deck-card-${items[active]?.id ?? ""}`}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={() => {
          dragRef.current = null;
        }}
        onWheel={handleWheel}
        onKeyDown={handleKeyDown}
      >
        {items.map((card, index) => {
          const offset = index - active;
          if (offset < 0 || offset >= VISIBLE) return null;
          const { tint, deep } = paletteFor(card);
          const isFront = offset === 0;
          const cardStyle = {
            "--deck-tint": tint,
            "--deck-deep": deep,
            transform: `translate3d(${offset * STEP_SHIFT}px, ${-offset * STEP_LIFT}px, ${-offset * 60}px) rotate(${offset * STEP_TILT}deg) scale(${1 - offset * (1 - STEP_SCALE)})`,
            opacity: 1 - offset * STEP_FADE,
            filter: offset > 0 ? `blur(${offset * STEP_BLUR}px)` : "none",
            zIndex: VISIBLE - offset,
          } as CSSProperties;

          return (
            <button
              type="button"
              key={card.id}
              id={`deck-card-${card.id}`}
              role="option"
              aria-selected={isFront}
              tabIndex={-1}
              className={["card-deck__card", isFront && "is-front"]
                .filter(Boolean)
                .join(" ")}
              style={cardStyle}
              onClick={() => {
                if (draggedRef.current) {
                  draggedRef.current = false;
                  return;
                }
                if (!isFront) {
                  step(index - active);
                  return;
                }
                onSelect?.(card);
              }}
            >
              <span className="card-deck__edge" aria-hidden="true" />
              {card.swatch?.length ? (
                <span className="card-deck__swatch" aria-hidden="true">
                  {card.swatch.map((color, swatchIndex) => (
                    <i key={swatchIndex} style={{ background: color }} />
                  ))}
                </span>
              ) : null}
              {card.image ? (
                <img className="card-deck__image" src={card.image} alt="" />
              ) : (
                <span className="card-deck__face">
                  {card.tag ? (
                    <span className="card-deck__tag">{card.tag}</span>
                  ) : null}
                  <span className="card-deck__word">{card.word}</span>
                  {card.meaning ? (
                    <span className="card-deck__meaning">{card.meaning}</span>
                  ) : null}
                  {typeof card.rounds === "number" ? (
                    <span className="card-deck__rounds">{card.rounds} 轮</span>
                  ) : null}
                </span>
              )}
            </button>
          );
        })}
      </div>
      {hint ? <p className="card-deck__hint">{hint}</p> : null}
    </div>
  );
}

export default CardDeck;
