/**
 * 竖屏降级方案的开关（手机竖屏）。
 *
 * 一处写死、两处引用：
 * - RotateGate 用它决定要不要请用户把手机横过来；
 * - WoodenBookshelf 用它决定要不要把手势认成「单指转书架 / 双指捏合缩放」。
 *
 * portrait-room.css 里的媒体查询必须和这条一字不差，改这里就得一起改；
 * pointer:coarse 把「窄而高的桌面窗口」挡在外面 —— 那不算手机竖屏。
 */
export const PORTRAIT_PHONE_QUERY =
  "(orientation: portrait) and (max-width: 640px) and (pointer: coarse)";

export function isPortraitPhone(): boolean {
  if (typeof window === "undefined" || !window.matchMedia) return false;
  return window.matchMedia(PORTRAIT_PHONE_QUERY).matches;
}

/** 订阅竖屏状态的变化（旋转手机、外接显示都会触发），返回退订函数。 */
export function watchPortraitPhone(
  listener: (portrait: boolean) => void,
): () => void {
  if (typeof window === "undefined" || !window.matchMedia) {
    return () => {};
  }
  const query = window.matchMedia(PORTRAIT_PHONE_QUERY);
  const handle = () => listener(query.matches);
  handle();
  query.addEventListener("change", handle);
  return () => query.removeEventListener("change", handle);
}
