import { Lock, Maximize2, Minimize2, RotateCw, X } from "lucide-react";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { cn } from "../../lib/cn";
import "./browser-frame.css";

/**
 * 一扇「浏览器窗口」。
 *
 * 词汇积累、练习空间这类内容不再是书房里的一张卡片，而是打开的网页：
 * 顶上一条标签页写着页面名，下面是地址栏（leafia:// 开头，跟真网址一样
 * 配一把小锁），再往下才是内容。整扇窗只有一个关闭按钮，钉在页面右上角
 * —— 左上角那颗红点退回它本来的身份：一盏灯，看着像窗口，按不动。
 *
 * 最右边那颗绿点也是真的：按下去整扇窗铺满屏幕，读长内容时看得下更多行，
 * 再按一下还原。放大之后 Esc 先还原这一层，不直接把整扇窗关掉。
 */
export function BrowserFrame({
  label,
  url,
  children,
  onClose,
  actions,
  className = "",
}: {
  /** 标签页上的页面名。 */
  label: string;
  /** 地址栏里的地址，例如 leafia://words。 */
  url: string;
  children: ReactNode;
  onClose?: () => void;
  /** 地址栏右侧的额外按钮。 */
  actions?: ReactNode;
  className?: string;
}) {
  const [expanded, setExpanded] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!expanded) return undefined;
    // 捕获阶段先接住：父级的 Esc 是关整扇窗，放大状态下先还原这一层。
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.stopPropagation();
      setExpanded(false);
    };
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, [expanded]);

  return (
    <div
      ref={rootRef}
      className={cn("browser-frame", expanded && "is-expanded", className)}
      role="dialog"
      aria-label={label}
    >
      <header className="browser-frame__chrome">
        <div className="browser-frame__dots">
          <span
            className="browser-frame__dot browser-frame__dot--close"
            aria-hidden="true"
          />
          <span className="browser-frame__dot browser-frame__dot--min" aria-hidden="true" />
          <button
            type="button"
            className="browser-frame__dot browser-frame__dot--max"
            onClick={() => setExpanded((value) => !value)}
            aria-label={expanded ? `还原 ${label}` : `放大 ${label}`}
            aria-pressed={expanded}
          >
            {expanded ? (
              <Minimize2 size={9} aria-hidden="true" />
            ) : (
              <Maximize2 size={9} aria-hidden="true" />
            )}
          </button>
        </div>
        <div className="browser-frame__tab">
          <span className="browser-frame__favicon" aria-hidden="true">
            {label.slice(0, 1).toUpperCase()}
          </span>
          <span className="browser-frame__tab-label">{label}</span>
        </div>
        <div className="browser-frame__bar">
          <Lock size={11} aria-hidden="true" />
          <span className="browser-frame__url">{url}</span>
          <RotateCw size={12} aria-hidden="true" className="browser-frame__reload" />
          {actions ? <span className="browser-frame__actions">{actions}</span> : null}
        </div>
        {/* 整扇窗唯一的 ✕，就钉在页面右上角。左上角那三颗圆点只是窗口
            的样子货（绿点除外，它真的会放大）。 */}
        {onClose ? (
          <button
            type="button"
            className="browser-frame__close"
            onClick={onClose}
            aria-label={`关闭 ${label}`}
          >
            <X size={15} aria-hidden="true" />
          </button>
        ) : null}
      </header>
      <div className="browser-frame__page">{children}</div>
    </div>
  );
}

export default BrowserFrame;
