import type { ReaderBook } from "../../lib/readerLibrary";

/**
 * 四层书架，从上往下数：
 *   01 单词本    —— 单词本
 *   02 知识库    —— 六本英语知识书（语言花园）
 *   03 练习册    —— 练习册 + 语言 / 词汇 / 写作 / 翻译四个分类本
 *   04 我的笔记  —— 三本笔记本只当陈设（inert），不接任何功能
 *
 * ⚠️ 数组顺序 = 从下往上（index 0 = 最底层，和 SHELF_Y 一致），
 * 编号却是从上往下数的 —— 所以 01 在数组末尾。改布局前先看清这一点。
 */
export const SHELF_LEVELS = [
  // 04 我的笔记：书和建模都还在架上，但这一层已经不着功能 —— 不发光、
  // 不响应指针、也没有无障碍入口。功能只剩 01/02/03 三层。
  { number: "04", english: "My Notes", chinese: "我的笔记", inert: true },
  { number: "03", english: "Practice Books", chinese: "练习册", inert: false },
  {
    number: "02",
    english: "Knowledge Library",
    chinese: "知识库",
    inert: false,
  },
  { number: "01", english: "Wordbook", chinese: "单词本", inert: false },
] as const;

const SHELF_CAPACITY = [3, 5, 6, 1] as const;

export interface ShelfRow {
  number: string;
  english: string;
  chinese: string;
  /** 纯陈设的一层：书站着，但不可点、不发光、不进无障碍列表。 */
  inert: boolean;
  books: ReaderBook[];
}

export function createShelfRows(books: ReaderBook[]): ShelfRow[] {
  let cursor = 0;

  return SHELF_LEVELS.map((level, rowIndex) => {
    const capacity = SHELF_CAPACITY[rowIndex] ?? 0;
    const rowBooks = books.slice(cursor, cursor + capacity);
    cursor += rowBooks.length;

    return {
      ...level,
      books: [...rowBooks],
    };
  });
}

export const REMOVED_READING_IDS = [
  "jane-eyre",
  "dracula",
  "oliver-twist",
  "three-musketeers",
] as const;

/**
 * 01 单词本：只有一本，点开的是房间里的词汇窗口（不翻页），见 WoodenBookshelf。
 */
export const WORDBOOK_BOOK_IDS = ["vocabulary"] as const;

/**
 * 03 练习册：练习册（综合台）+ 语言 / 词汇 / 写作 / 翻译四个分类本。
 * 分类本各自指向那一类练习的主场；练习册本体去 /practice。
 * 前两本不在 BOOKS 里，是书架上现搭的板板书（见 WoodenBookshelf）。
 */
export const PRACTICE_ROW_BOOK_IDS = [
  "practice-space",
  "practice-language",
  "practice-vocabulary",
  "practice-writing",
  "practice-translation",
] as const;
export const PRACTICE_BOOK_ID = "practice-space";

const PRACTICE_BOOK_TARGETS: Record<string, string> = {
  "practice-space": "/practice",
  "practice-language": "/drill/language",
  "practice-vocabulary": "/drill/vocabulary",
  "practice-writing": "/drill/writing",
  "practice-translation": "/drill/translation",
};

/** 04 我的笔记：三个笔记本。 */
export const NOTE_BOOK_IDS = [
  "notebook-index",
  "commonplace",
  "custom",
] as const;

const KNOWLEDGE_BY_CORE_BOOK: Record<string, string> = {
  "core-language": "knowledge-linguistics",
  "core-literature": "knowledge-literature",
  "core-culture": "knowledge-culture",
  "core-translation": "knowledge-translation",
  "core-writing": "knowledge-writing",
  "core-lexicology": "knowledge-vocabulary",
};

export function shelfBookDestination(id: string) {
  const base = id.split("#")[0] ?? id;
  const knowledgeBook = KNOWLEDGE_BY_CORE_BOOK[base];
  if (knowledgeBook) return `/book/${knowledgeBook}`;
  const practiceTarget = PRACTICE_BOOK_TARGETS[base];
  if (practiceTarget) return practiceTarget;
  if (base === "vocabulary") return "/vocabulary";
  if (base === "commonplace") return "/corpus";
  if (base === "notebook-index") return "/library";
  return `/book/${base}`;
}
